svg.script:
//
    (function() {
      'use strict';

      var currentStep = 4;

      var layerT1 = document.getElementById('a12p4h-layer-t1');
      var layerT2 = document.getElementById('a12p4h-layer-t2');
      var layerT3 = document.getElementById('a12p4h-layer-t3');
      var layerT4 = document.getElementById('a12p4h-layer-t4');

      var btn1 = document.getElementById('a12p4h-btn-step-1');
      var btn2 = document.getElementById('a12p4h-btn-step-2');
      var btn3 = document.getElementById('a12p4h-btn-step-3');
      var btn4 = document.getElementById('a12p4h-btn-step-4');

      var infoTitle = document.getElementById('a12p4h-info-title');
      var line1 = document.getElementById('a12p4h-info-line1');
      var line2 = document.getElementById('a12p4h-info-line2');
      var line3 = document.getElementById('a12p4h-info-line3');
      var line4 = document.getElementById('a12p4h-info-line4');
      var line5 = document.getElementById('a12p4h-info-line5');

      var stepData = {
        1: {
          title: "TEMPO 1: A PAREDE POSTERIOR",
          l1: "O Sacro e Cóccix formam o pilar rígido posterior.",
          l2: "Suportam diretamente a coluna L5.",
          l3: "Pertencem ao esqueleto axial.",
          l4: "Ponto de ancoragem superior da carga corporal.",
          l5: "(Base de sustentação posterior do tronco)."
        },
        2: {
          title: "TEMPO 2: AS PAREDES LATERAIS",
          l1: "2 Ossos do Quadril fecham as laterais.",
          l2: "Articulam-se nas Sacroilíacas (D/E).",
          l3: "Cada quadril une Ílio, Ísquio e Púbis.",
          l4: "Transferem o peso para as cavidades acetabulares.",
          l5: "(Estrutura apendicular de transmissão)."
        },
        3: {
          title: "TEMPO 3: O FECHAMENTO ANTERIOR",
          l1: "A Sínfise Púbica une os ramos púbicos na frente.",
          l2: "Funciona como tirante de tensão anterior.",
          l3: "Impede o afastamento dos ossos ilíacos.",
          l4: "Maneja forças de tração durante o apoio de carga.",
          l5: "(Trava mecânica sem vetor de peso axial)."
        },
        4: {
          title: "ROTA DE CARGA: TRANSMISSÃO AXIAL",
          l1: "A carga peso da coluna desce por",
          l2: "L5 → Sacro → Sacroilíacas → Quadris → Fêmures.",
          l3: "A Sínfise Púbica atua como tirante de tensão,",
          l4: "impedindo a abertura anterior do anel.",
          l5: "(Não transmite força gravitacional axial)."
        }
      };

      function setStep(step) {
        currentStep = step;

        if (btn1) btn1.setAttribute('class', 'a12p4h-btn' + (step === 1 ? ' a12p4h-active' : ''));
        if (btn2) btn2.setAttribute('class', 'a12p4h-btn' + (step === 2 ? ' a12p4h-active' : ''));
        if (btn3) btn3.setAttribute('class', 'a12p4h-btn' + (step === 3 ? ' a12p4h-active' : ''));
        if (btn4) btn4.setAttribute('class', 'a12p4h-btn' + (step === 4 ? ' a12p4h-active' : ''));

        if (step === 1) {
          if (layerT1) layerT1.setAttribute('class', 'a12p4h-tempo-grp a12p4h-visible');
          if (layerT2) layerT2.setAttribute('class', 'a12p4h-tempo-grp a12p4h-hidden');
          if (layerT3) layerT3.setAttribute('class', 'a12p4h-tempo-grp a12p4h-hidden');
          if (layerT4) layerT4.setAttribute('class', 'a12p4h-tempo-grp a12p4h-hidden');
        } else if (step === 2) {
          if (layerT1) layerT1.setAttribute('class', 'a12p4h-tempo-grp a12p4h-visible');
          if (layerT2) layerT2.setAttribute('class', 'a12p4h-tempo-grp a12p4h-visible');
          if (layerT3) layerT3.setAttribute('class', 'a12p4h-tempo-grp a12p4h-hidden');
          if (layerT4) layerT4.setAttribute('class', 'a12p4h-tempo-grp a12p4h-hidden');
        } else if (step === 3) {
          if (layerT1) layerT1.setAttribute('class', 'a12p4h-tempo-grp a12p4h-visible');
          if (layerT2) layerT2.setAttribute('class', 'a12p4h-tempo-grp a12p4h-visible');
          if (layerT3) layerT3.setAttribute('class', 'a12p4h-tempo-grp a12p4h-visible');
          if (layerT4) layerT4.setAttribute('class', 'a12p4h-tempo-grp a12p4h-hidden');
        } else if (step === 4) {
          if (layerT1) layerT1.setAttribute('class', 'a12p4h-tempo-grp a12p4h-visible a12p4h-dimmed');
          if (layerT2) layerT2.setAttribute('class', 'a12p4h-tempo-grp a12p4h-visible a12p4h-dimmed');
          if (layerT3) layerT3.setAttribute('class', 'a12p4h-tempo-grp a12p4h-visible a12p4h-dimmed');
          if (layerT4) layerT4.setAttribute('class', 'a12p4h-tempo-grp a12p4h-visible');
        }

        var data = stepData[step];
        if (data) {
          if (infoTitle) infoTitle.textContent = data.title;
          if (line1) line1.textContent = data.l1;
          if (line2) line2.textContent = data.l2;
          if (line3) line3.textContent = data.l3;
          if (line4) line4.textContent = data.l4;
          if (line5) line5.textContent = data.l5;
        }
      }

      if (btn1) btn1.addEventListener('click', function() { setStep(1); });
      if (btn2) btn2.addEventListener('click', function() { setStep(2); });
      if (btn3) btn3.addEventListener('click', function() { setStep(3); });
      if (btn4) btn4.addEventListener('click', function() { setStep(4); });

      var hsSacrum = document.getElementById('a12p4h-hs-sacrum');
      var hsHipR = document.getElementById('a12p4h-hs-hip-r');
      var hsHipL = document.getElementById('a12p4h-hs-hip-l');
      var hsSymph = document.getElementById('a12p4h-hs-symph');

      if (hsSacrum) hsSacrum.addEventListener('click', function() { setStep(1); });
      if (hsHipR) hsHipR.addEventListener('click', function() { setStep(2); });
      if (hsHipL) hsHipL.addEventListener('click', function() { setStep(2); });
      if (hsSymph) hsSymph.addEventListener('click', function() { setStep(3); });

      setStep(4);
    })();
  //
